import os
import requests

def normalize_expense(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ["MINDEE_API_KEY"]
    response = requests.post(
        "https://api.mindee.net/v1/products/mindee/expense_receipts/v5/predict",
        headers={"Authorization": f"Token {api_key}"},
        files={"document": ("document", payload if isinstance(payload, (bytes, bytearray)) else str(payload).encode("utf-8"))},
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()
    prediction = data.get("document", {}).get("inference", {}).get("prediction", {})
    supplier = prediction.get("supplier_name", {}) or {}
    total_amount = prediction.get("total_amount", {}) or {}
    date = prediction.get("date", {}) or {}
    taxes = prediction.get("taxes", []) or []
    locale = prediction.get("locale", {}) or {}
    document_type = prediction.get("document_type", {}) or {}
    line_items = prediction.get("line_items", []) or []
    result = {
        "vendor_name": supplier.get("value"),
        "invoice_date": date.get("value"),
        "total": total_amount.get("value"),
        "currency": locale.get("currency"),
        "document_type": document_type.get("value"),
        "taxes": [
            {
                "amount": tax.get("value"),
                "rate": tax.get("rate"),
                "code": tax.get("code"),
            }
            for tax in taxes
        ],
        "line_items": [
            {
                "description": item.get("description"),
                "quantity": item.get("quantity"),
                "unit_price": item.get("unit_price"),
                "total": item.get("total_amount"),
            }
            for item in line_items
        ],
        "raw": data,
    }
    return result
